import { worktreeGitEnvironment } from "@nosh/git-workspaces";
import { createId } from "@nosh/core";
import { ArtifactStore } from "@nosh/evidence";
import { existsSync, mkdirSync, readFileSync, renameSync, unlinkSync, writeFileSync } from "node:fs";
import { VersionedDag, type GraphNode } from "@nosh/graph";
import type { PiAdapter, PiSessionOptions } from "@nosh/pi-adapter";
import type { OrchestrationRuntime } from "@nosh/orchestration-runtime";
import type { RegisteredProject } from "@nosh/persistence";
import { Scheduler } from "@nosh/scheduler";
import { canonicalJson, schemaUri, sha256, validateRecord, type EventDraft, type JsonValue, type TaskPermissions, episodeTypeForRole } from "@nosh/wire";
import { spawnSync } from "node:child_process";
import { join, relative, resolve } from "node:path";
import { daemonTaskFacts, declaredTaskCommands, librarianNetworkAllowed, librarianResearchHosts, taskCommandInstructions, taskCommandRuns, type DirectionProjection, type ResearchControl, type Stored } from "./research-control.js";
import { completionRunIssues, validateGitCompletion } from "./task-postflight.js";
import { directionAutoresearchOutcomes, directionBrief } from "./director-brief.js";
import { createTaskWorktree, taskWorktreePath } from "./task-worktree.js";
import { completionInstructions, generalWorkerCompletionTemplate, librarianInstructions, reviewerInstructions, type DaemonEvaluation } from "./task-templates.js";
import { loadNativeEvaluation, type JobRecord, type JobSpec } from "@nosh/jobs";

export class DirectionSupervisor {
  private timer: NodeJS.Timeout | undefined; private readonly busy = new Set<string>(); private readonly awaiting = new Set<string>(); private readonly scheduler = new Scheduler();
  constructor(private readonly research: ResearchControl, private readonly agents: PiAdapter, private readonly projects: () => RegisteredProject[], private readonly packagePath: string, private readonly emit: (draft: EventDraft) => void, private readonly runtime?: OrchestrationRuntime, private readonly jobRunner?: { start(spec: JobSpec): JobRecord; get(jobId: string): JobRecord }) {}
  // Each cycle records its own failures as events; only failures after shutdown (closed stores) reach here.
  start(): void { this.timer = setInterval(() => void this.tick().catch(() => undefined), 1_000); this.timer.unref(); }
  stop(): void { if (this.timer) clearInterval(this.timer); this.timer = undefined; }
  async tick(): Promise<void> { for (const project of this.projects()) for (const direction of this.research.directions(project.projectId)) if (direction.state === "active") void this.cycle(project, direction.entityId).catch(() => undefined); }

  private async cycle(project: RegisteredProject, directionId: string): Promise<void> {
    if (this.busy.has(directionId) || this.agents.inspect().some((agent) => agent.directionId === directionId)) return; const owner = this.research.direction(project.projectId, directionId); if (this.runtime?.hasActiveFork(project.projectId, owner.value.missionId, directionId)) return; this.busy.add(directionId);
    try {
      let direction = this.research.direction(project.projectId, directionId); if (direction.state !== "active") return; direction = this.reconcileOrphanedNodes(project.projectId, direction); if (direction.state !== "active") return; const graph = new VersionedDag(directionId, direction.value.nodes, "hydrated", direction.value.graphVersion); if (graph.completionReady()) { await this.close(project, direction); return; }
      const node = this.scheduler.frontier(graph, { paused: false, approvals: new Set(), workspaceConflicts: new Set(), availableRoles: new Set(["librarian_researcher", "general_worker", "reviewer"]), available: { agents: 1, gpuJobs: 0, gpuSeconds: 0, modelTokens: Number.MAX_SAFE_INTEGER, diskBytes: Number.MAX_SAFE_INTEGER } })[0]; if (!node) { if (!direction.value.nodes.some((item) => ["leased", "working", "postflight", "reviewing"].includes(item.state))) this.research.transitionDirection(project.projectId, directionId, direction.version, "blocked", `direction-blocked-${createId("cmd")}`); return; }
      // Hypothesis evaluation is experiment work: the Direction-backed Autoresearch fulfils it, not a single worker.
      if (isHypothesisNode(node)) { this.awaitAutoresearch(project, direction, node); return; }
      await this.director(project, direction, node); direction = this.research.direction(project.projectId, directionId); if (direction.state === "active") await this.runNode(project, direction, node.id);
    } catch (error) { let direction = this.research.direction(project.projectId, directionId); this.emit(event(project.projectId, directionId, direction.value.missionId, "direction.supervisor_error", { message: error instanceof Error ? error.message : "Direction supervisor failed" })); if (direction.state === "reviewing") direction = this.research.transitionDirection(project.projectId, directionId, direction.version, "active", `direction-review-failed-${createId("cmd")}`); if (direction.state === "active") this.research.transitionDirection(project.projectId, directionId, direction.version, "blocked", `direction-error-${createId("cmd")}`); }
    finally { this.busy.delete(directionId); }
  }

  private async director(project: RegisteredProject, direction: Stored<DirectionProjection>, node: GraphNode): Promise<void> {
    const agentId = createId("agt"); const taskId = createId("tsk");
    const brief = directionBrief({ research: this.research, project, direction, node, agentId });
    await this.session(project, direction, agentId, taskId, "research_director", brief.prompt);
    const record = this.research.terminalRecord(project.projectId, taskId, "research-director-cycle") as { cycleId?: string; directorAgentId?: string; directionId?: string; observedGraphVersion?: number; evaluationContractHash?: string; questionCheck?: { currentWorkContributes?: boolean } } | undefined;
    if (!record || record.cycleId !== brief.ids.cycleId || record.directorAgentId !== agentId || record.directionId !== direction.entityId || record.observedGraphVersion !== direction.value.graphVersion || record.evaluationContractHash !== direction.value.evaluationContractHash) throw new Error("Research Director did not submit the current cycle record");
    // A valid "does not contribute" decision is the director halting work, not a supervisor fault.
    if (record.questionCheck?.currentWorkContributes !== true) { this.emit(event(project.projectId, direction.entityId, direction.value.missionId, "direction.director_halted", { cycleId: record.cycleId, nodeId: node.id })); throw new Error("Research Director halted the selected node; user attention required"); }
  }
  /**
   * Resolve the hypothesis node from the Direction's Autoresearch outcome (Autoresearch carries its
   * own closure Review). Each execution is consumed once: a stopped or failed one costs a node
   * attempt, after which the node waits for a new execution while attempts remain.
   */
  private awaitAutoresearch(project: RegisteredProject, direction: Stored<DirectionProjection>, node: GraphNode): void {
    const projectId = project.projectId; const id = direction.entityId;
    const consumed = new Set(this.research.eventsAfter(projectId, 0).filter((entry) => entry.type === "direction.hypothesis_resolved" && entry.scope.directionId === id && (entry.payload as { nodeId?: string }).nodeId === node.id).map((entry) => String((entry.payload as { autoresearchId?: string }).autoresearchId)));
    const runs = this.research.autoresearch(projectId).filter((run) => run.value.directionId === id && !consumed.has(run.entityId));
    const completed = runs.find((run) => run.state === "completed");
    const finished = runs.find((run) => ["failed", "stopped"].includes(run.state));
    if (!completed && !finished) {
      if (!this.awaiting.has(node.id)) { this.awaiting.add(node.id); this.emit(event(projectId, id, direction.value.missionId, "direction.awaiting_autoresearch", { nodeId: node.id, autoresearchIds: runs.map((run) => run.entityId), action: "Create and start a Direction-backed Autoresearch (TUI: /create autoresearch <file>, then /transition autoresearch <id> <version> running)." })); }
      return;
    }
    const source = completed ?? finished!; const key = `direction-hypothesis-${source.entityId}`; this.awaiting.delete(node.id);
    let current = this.research.transitionDirectionNode(projectId, id, direction.version, node.id, "leased", `${key}-leased`, { leaseId: `lease_${source.entityId.slice(3)}`, ownerId: source.entityId, version: direction.version, expiresAt: new Date(Date.now() + 60_000).toISOString() });
    current = this.research.transitionDirectionNode(projectId, id, current.version, node.id, "working", `${key}-working`);
    this.emit(event(projectId, id, direction.value.missionId, "direction.hypothesis_resolved", { nodeId: node.id, autoresearchId: source.entityId, outcome: completed ? "accepted" : source.state }));
    if (completed) for (const next of ["postflight", "reviewing", "accepted"] as const) current = this.research.transitionDirectionNode(projectId, id, current.version, node.id, next, `${key}-${next}`);
    else this.fail(projectId, id, node.id, source.entityId);
  }
  private reconcileOrphanedNodes(projectId: string, direction: Stored<DirectionProjection>): Stored<DirectionProjection> { for (const stale of direction.value.nodes.filter((node) => ["leased", "working", "postflight", "reviewing"].includes(node.state))) { if (stale.state === "leased") direction = this.research.transitionDirectionNode(projectId, direction.entityId, direction.version, stale.id, "ready", `direction-recovery-release-${stale.lease?.leaseId ?? createId("cmd")}`); else { direction = this.research.transitionDirectionNode(projectId, direction.entityId, direction.version, stale.id, "failed", `direction-recovery-failed-${stale.lease?.leaseId ?? createId("cmd")}`); const current = direction.value.nodes.find((node) => node.id === stale.id)!; if (current.attempt < current.maximumAttempts) direction = this.research.transitionDirectionNode(projectId, direction.entityId, direction.version, stale.id, "ready", `direction-recovery-ready-${stale.lease?.leaseId ?? createId("cmd")}`); else { this.emit(event(projectId, direction.entityId, direction.value.missionId, "direction.node_recovered", { nodeId: stale.id, priorState: stale.state, disposition: "attempt_budget_exhausted" })); return this.research.transitionDirection(projectId, direction.entityId, direction.version, "blocked", `direction-recovery-blocked-${stale.lease?.leaseId ?? createId("cmd")}`); } } this.emit(event(projectId, direction.entityId, direction.value.missionId, "direction.node_recovered", { nodeId: stale.id, priorState: stale.state, disposition: "ready_for_new_lease" })); } return direction; }

  private async runNode(project: RegisteredProject, direction: Stored<DirectionProjection>, nodeId: string): Promise<void> {
    let node = direction.value.nodes.find((item) => item.id === nodeId); if (!node || node.state !== "ready") return; this.scheduler.recordAllocation(nodeId); const role = roleFor(node); const agentId = createId("agt"); const taskId = createId("tsk"); const expiresAt = new Date(Date.now() + 30 * 60_000).toISOString(); direction = this.research.transitionDirectionNode(project.projectId, direction.entityId, direction.version, nodeId, "leased", `direction-lease-${taskId}`, { leaseId: taskId, ownerId: agentId, version: direction.version, expiresAt }); direction = this.research.transitionDirectionNode(project.projectId, direction.entityId, direction.version, nodeId, "working", `direction-working-${taskId}`); node = direction.value.nodes.find((item) => item.id === nodeId)!; const schema = role === "reviewer" ? "review-verdict" : role === "librarian_researcher" ? "librarian-completion" : "general-worker-completion"; let packet: DirectionTaskPacket; let directReview: DirectionReviewRequest | null = null; let outcomes: { evidenceIds: string[]; digest: string } = { evidenceIds: [], digest: "" };
    let evaluation: DaemonEvaluation | null = null;
    try { packet = this.issueTaskPacket(project, direction, node, agentId, taskId, role, schema, expiresAt); if (role === "general_worker" && isBaselineNode(node)) evaluation = await this.evaluateBaseline(project, direction, packet); if (role === "reviewer") { const producer = [...this.research.records(project.projectId, "research-director-cycle")].reverse().find((record) => (record as { directionId?: string }).directionId === direction.entityId) as { directorAgentId?: string } | undefined; if (!producer?.directorAgentId) throw new Error("Direction Review requires a durable producer identity"); outcomes = directionAutoresearchOutcomes(this.research, project.projectId, direction.entityId); directReview = this.issueReviewRequest(project, direction, taskId, agentId, [producer.directorAgentId], "task", "graph_node", node.id, direction.version, node.id, node.title, [], outcomes.evidenceIds); } await this.session(project, direction, agentId, taskId, role, `Daemon-issued Task Packet: ${JSON.stringify(packet)}. Complete only Direction node ${node.id}: ${node.title}. You work in an isolated worktree on branch ${packet.workspace.branch}. ${evaluation ? `The daemon ran the frozen evaluation command as supervised Job ${evaluation.jobId} at commit ${packet.workspace.startingCommit}: state ${evaluation.state}, exit code ${evaluation.exitCode}, metrics ${JSON.stringify(evaluation.metrics)}, metrics artifact ${evaluation.metricArtifactId ?? "none"}${evaluation.failure ? `, failure: ${evaluation.failure}` : ""}. You cannot run commands; audit this result against the frozen evaluation contract and its baseline, and claim each criterion only as far as this evidence supports it. ` : ""}${directReview ? `${outcomes.digest ? `Resolved Autoresearch outcomes for this Direction (daemon-authored; the required Evidence holds these statements): ${outcomes.digest} ` : ""}Review Request: ${JSON.stringify(directReview)}. ` : ""}${role === "general_worker" ? completionInstructions(generalWorkerCompletionTemplate(packet, evaluation)) : role === "reviewer" && directReview ? reviewerInstructions(directReview) : role === "librarian_researcher" ? librarianInstructions(taskId, packet.permissions.network === "allowlisted") : `Submit exactly one ${schemaUri(schema)} in the host terminal JSON envelope.`}`, packet.permissions, packet.workspace); } catch (error) { this.emit(event(project.projectId, direction.entityId, direction.value.missionId, "direction.task_failed", { taskId, nodeId, message: error instanceof Error ? error.message : "Direction task failed" })); this.fail(project.projectId, direction.entityId, node.id, taskId); return; }
    if (role === "reviewer") { direction = this.research.transitionDirectionNode(project.projectId, direction.entityId, direction.version, node.id, "postflight", `direction-postflight-${taskId}`); direction = this.research.transitionDirectionNode(project.projectId, direction.entityId, direction.version, node.id, "reviewing", `direction-reviewing-${taskId}`); this.applyReview(project.projectId, direction, node.id, taskId, agentId, null, directReview!); return; }
    const completion = this.research.terminalRecord(project.projectId, taskId, schema); const issues = completion ? [...directionPostflight(project, packet, schema, completion), ...completionRunIssues(taskCommandRuns(this.research)(project.projectId), taskId, completion)] : ["missing completion record"]; if (issues.length) { this.emit(event(project.projectId, direction.entityId, direction.value.missionId, "direction.postflight_failed", { taskId, nodeId, issues })); this.fail(project.projectId, direction.entityId, node.id, taskId); return; }
    direction = this.research.transitionDirectionNode(project.projectId, direction.entityId, direction.version, node.id, "postflight", `direction-postflight-${taskId}`); direction = this.research.transitionDirectionNode(project.projectId, direction.entityId, direction.version, node.id, "reviewing", `direction-reviewing-${taskId}`); const refs = completionRefs(completion!); const reviewerId = createId("agt"); const reviewTask = createId("tsk"); const request = this.issueReviewRequest(project, direction, reviewTask, reviewerId, [agentId], "task", "graph_node", node.id, direction.version, node.id, node.title, refs.artifactIds, refs.evidenceIds); await this.session(project, direction, reviewerId, reviewTask, "reviewer", `Independently review Direction node ${node.id}: ${node.title}. Worker ${agentId} submitted ${JSON.stringify(completion)} under contract ${direction.value.evaluationContractHash}. ${daemonTaskFacts(this.research, project.projectId, taskId)} Review Request: ${JSON.stringify(request)}. ${evaluation ? `Daemon-recorded evaluation (authoritative): Job ${evaluation.jobId}, state ${evaluation.state}, exit code ${evaluation.exitCode}, metrics ${JSON.stringify(evaluation.metrics)}, metrics artifact ${evaluation.metricArtifactId ?? "none"}. ` : ""}${reviewerInstructions(request)}`); const commit = (completion as unknown as { codeChanges?: { endingCommit?: string } }).codeChanges?.endingCommit ?? null; this.applyReview(project.projectId, direction, node.id, reviewTask, reviewerId, commit, request);
  }

  /** Baseline nodes are reproduced by the daemon, not the model: run the frozen command as a supervised Job. */
  private async evaluateBaseline(project: RegisteredProject, direction: Stored<DirectionProjection>, packet: DirectionTaskPacket): Promise<DaemonEvaluation | null> {
    if (!this.jobRunner) return null;
    const execution = (direction.value.evaluationContract as { execution?: { runner?: "native" | "wsl2"; distribution?: string | null; command?: string[]; resultPath?: string; timeoutSeconds?: number; usesGpu?: boolean } }).execution;
    if (!execution?.command?.length || !execution.resultPath) throw new Error("Direction evaluation contract has no runnable execution command");
    const worktree = taskWorktreePath(project.repositoryRoot, packet.workspace.worktreeId); const resultPath = resolve(worktree, execution.resultPath);
    if (relative(worktree, resultPath).startsWith("..")) throw new Error("Evaluation result path escapes the worktree");
    const jobId = createId("job"); const timeoutSeconds = execution.timeoutSeconds ?? 600; const displayCommand = execution.command.join(" ");
    this.jobRunner.start({ jobId, projectId: project.projectId, missionId: direction.value.missionId, directionId: direction.entityId, autoresearchId: null, runId: createId("run"), experimentId: direction.value.plannedBaselineExperimentId, commitSha: packet.workspace.startingCommit, workingDirectory: worktree, runner: execution.runner ?? "native", distribution: execution.distribution ?? null, command: execution.command, checkpointCommand: null, environmentLockHash: sha256({ node: process.version, platform: process.platform, arch: process.arch }), evaluationContractHash: direction.value.evaluationContractHash, timeoutSeconds, usesGpu: execution.usesGpu === true });
    const terminal = ["completed", "failed", "cancelled", "lost"]; let job = this.jobRunner.get(jobId); const deadline = Date.now() + (timeoutSeconds + 60) * 1_000;
    while (!terminal.includes(job.state) && Date.now() < deadline) { await new Promise((done) => setTimeout(done, 500)); job = this.jobRunner.get(jobId); }
    if (!terminal.includes(job.state)) throw new Error(`Baseline evaluation Job ${jobId} did not finish within its timeout`);
    let metrics: JsonValue = { error: job.failureReason ?? job.state }; let failure: string | null = job.state === "completed" ? "evaluation result file is absent" : `job ${job.state}`; let metricArtifactId: string | null = null;
    if (job.state === "completed" && existsSync(resultPath)) {
      try { const loaded = loadNativeEvaluation(resultPath); if (loaded && typeof loaded === "object" && !Array.isArray(loaded)) { metrics = loaded; failure = null; } else failure = "evaluation result is not a JSON object"; }
      catch (error) { failure = error instanceof Error ? error.message : "evaluation result is malformed"; }
      metricArtifactId = this.jobArtifact(project, direction, "artifact_metrics", "application/json", resultPath, failure ? "negative_evidence" : "accepted_evidence");
      // An untracked result file would make the task worktree dirty for postflight; its content is now an artifact.
      if (directionGit(worktree, ["status", "--porcelain", "--", execution.resultPath]).startsWith("??")) unlinkSync(resultPath);
    }
    for (const [kind, path] of [["artifact_stdout.log", job.stdoutPath], ["artifact_stderr.log", job.stderrPath]] as const) if (existsSync(path)) this.jobArtifact(project, direction, kind, "text/plain", path, "negative_evidence");
    this.emit(event(project.projectId, direction.entityId, direction.value.missionId, "direction.baseline_evaluated", { jobId, state: job.state, exitCode: job.exitCode, metrics, metricArtifactId, failure }));
    return { jobId, state: job.state, exitCode: job.exitCode, displayCommand, metrics, metricArtifactId, failure };
  }
  private jobArtifact(project: RegisteredProject, direction: Stored<DirectionProjection>, kind: string, mediaType: string, sourcePath: string, retentionClass: "accepted_evidence" | "negative_evidence"): string {
    const artifactId = createId("art"); const artifact = new ArtifactStore(join(project.repositoryRoot, ".nosh", "artifacts")).add({ artifactId, projectId: project.projectId, kind, mediaType, sourcePath, retentionClass });
    const record: JsonValue = { $schema: schemaUri("artifact"), schemaVersion: 1, artifactId, projectId: project.projectId, kind, mediaType, contentHash: artifact.contentHash, sizeBytes: artifact.sizeBytes, version: artifact.version, producer: { type: "noshd" }, scope: { missionId: direction.value.missionId, directionId: direction.entityId, autoresearchId: null, experimentId: null }, git: null, evaluationContractHash: direction.value.evaluationContractHash, retentionClass, remotePreviewPolicy: "encrypted_allowed", redactionStatus: "checked", createdAt: artifact.createdAt };
    this.research.submitDaemonRecord(project.projectId, { projectId: project.projectId, missionId: direction.value.missionId, directionId: direction.entityId, autoresearchId: null, experimentId: null, runId: null, jobId: null, agentId: null }, `artifact:${artifactId}`, record, `direction-job-artifact:${artifactId}`);
    return artifactId;
  }
  private applyReview(projectId: string, direction: Stored<DirectionProjection>, nodeId: string, taskId: string, reviewerId: string, commit: string | null, request: DirectionReviewRequest): void { const review = this.research.terminalRecord(projectId, taskId, "review-verdict") as DirectionReviewVerdict | undefined; if (review && directionReviewPasses(review, request, reviewerId)) { direction = this.research.transitionDirectionNode(projectId, direction.entityId, direction.version, nodeId, "accepted", `direction-accepted-${taskId}`); if (!direction.value.acceptedBaseline && commit && review.reviewId) this.research.acceptDirectionBaseline(projectId, direction.entityId, direction.version, { commit, reviewId: review.reviewId, evaluationContractHash: direction.value.evaluationContractHash, idempotencyKey: `direction-baseline-${taskId}` }); return; } if (review?.verdict === "BLOCKED" && review.reviewId === request.reviewId && review.reviewRequestId === request.reviewRequestId) { this.research.transitionDirectionNode(projectId, direction.entityId, direction.version, nodeId, "blocked", `direction-review-blocked-${taskId}`); return; } this.fail(projectId, direction.entityId, nodeId, taskId); }
  private issueTaskPacket(project: RegisteredProject, direction: Stored<DirectionProjection>, node: GraphNode, agentId: string, taskId: string, role: "librarian_researcher" | "general_worker" | "reviewer", responseSchema: string, expiresAt: string): DirectionTaskPacket {
    const head = directionGit(project.repositoryRoot, ["rev-parse", "HEAD"]);
    const branch = directionGit(project.repositoryRoot, ["branch", "--show-current"]);
    if (!branch || directionGit(project.repositoryRoot, ["status", "--porcelain"])) throw new Error("Direction Task preflight requires a clean checked-out Git branch");
    const tree = createTaskWorktree(this.research, project, taskId, head);
    const libraryNetwork = role === "librarian_researcher" && librarianNetworkAllowed(project);
    const commands = role === "general_worker" ? declaredTaskCommands(project) : [];
    const permissions: TaskPermissions = {
      network: libraryNetwork ? "allowlisted" : "disabled",
      subprocess: commands.length ? "allowlisted" : "disabled",
      gitCommit: role === "general_worker",
      gitPush: false,
      delegation: "request_only",
      networkAllowlist: libraryNetwork ? [...librarianResearchHosts] : [],
      allowedToolIds: [
        role === "reviewer" ? "tool_nosh.review.submit" : "tool_nosh.response.submit",
        "tool_nosh.blocker.submit",
        ...(role === "reviewer" ? [] : ["tool_nosh.delegation.request"]),
        "tool_pi.read",
        ...(role === "reviewer" ? [] : ["tool_pi.edit", "tool_pi.write"]),
        ...(role === "general_worker" ? ["tool_nosh.git.commit"] : []),
        ...(libraryNetwork ? ["tool_nosh.network.read"] : []),
        ...(commands.length ? ["tool_nosh.run"] : []),
      ],
    };
    const packet: DirectionTaskPacket = {
      $schema: schemaUri("task-packet"), schemaVersion: 1, templateVersion: "1.0.0",
      taskId, attempt: node.attempt, taskType: `task_${node.type.replaceAll("_", ".")}`, assignedRole: role, assignedAgentId: agentId,
      scope: { projectId: project.projectId, missionId: direction.value.missionId, directionId: direction.entityId, autoresearchId: null, experimentId: null, graphNodeId: node.id },
      goalStack: { projectGoalId: project.projectId, projectGoalSummary: direction.value.decisionUse, missionCriterionIds: direction.value.missionId ? [direction.value.missionId] : [], missionCriterionSummary: direction.value.decisionUse, directionQuestionId: `question_${direction.entityId.slice(4)}`, directionQuestionSummary: direction.value.question, nodeObjective: node.title },
      whyNow: "The deterministic Direction frontier selected this ready node.",
      instructions: [`Complete only ${node.title}`, "Preserve the frozen evaluation contract", ...(commands.length ? taskCommandInstructions(commands) : ["You cannot run commands: report only what you verified by reading, and claim a criterion satisfied only as far as that evidence supports"])],
      inScope: ["**"], outOfScope: [".nosh/contracts/**"], inputArtifactIds: [], inputEvidenceIds: [],
      requiredOutputs: [{ outputId: `output_${taskId.slice(4)}`, kind: role === "general_worker" ? "output_code.commit" : role === "librarian_researcher" ? "output_research.report" : "output_review.verdict", required: true }],
      acceptanceCriteria: [{ criterionId: node.id, statement: node.title, validatorIds: ["validator_direction.postflight"], reviewRubricIds: ["rubric_scientific.correctness"], required: true }],
      workspace: { worktreeId: tree.worktreeId, branch: tree.branch, startingCommit: head, writeScopes: ["**"], protectedScopes: [".nosh/contracts/**"] },
      permissions,
      budget: { deadline: expiresAt, maximumWallClockSeconds: 7_200, maximumModelTokens: 60_000, maximumToolCalls: 100, maximumRepairAttempts: Math.max(0, node.maximumAttempts - node.attempt) },
      progressPolicy: { milestoneIntervalSeconds: 900, emitOnFirstDurableDelta: true, emitOnBlocker: true, emitOnAnomaly: true, maximumSilentSeconds: 1_200 },
      responseSchema: schemaUri(responseSchema),
      observedVersions: { directionGraphVersion: direction.value.graphVersion, directionProjectionVersion: direction.version },
      lease: { leaseId: taskId, expiresAt, heartbeatSeconds: 15 }, issuedBy: "research_director", issuedAt: new Date().toISOString(),
    };
    this.research.submitDaemonRecord(project.projectId, { projectId: project.projectId, missionId: direction.value.missionId, directionId: direction.entityId, autoresearchId: null, experimentId: null, runId: null, jobId: null, agentId }, `task:${taskId}`, packet as unknown as JsonValue, `direction-task-packet:${taskId}`);
    return packet;
  }
  private issueReviewRequest(project: RegisteredProject, direction: Stored<DirectionProjection>, taskId: string, reviewerAgentId: string, producerAgentIds: string[], reviewType: DirectionReviewRequest["reviewType"], targetType: string, targetId: string, targetVersion: number, criterionId: string, statement: string, artifacts: string[], evidence: string[]): DirectionReviewRequest { const producers = [...new Set(producerAgentIds)]; if (!producers.length || producers.includes(reviewerAgentId)) throw new Error("Direction Review requires an independent producer"); const reviewId = createId("rev"); const request: DirectionReviewRequest = { $schema: schemaUri("review-request"), schemaVersion: 1, reviewRequestId: `request_${reviewId.slice(4)}`, reviewId, reviewType, target: { targetType, targetId, targetVersion }, scope: { projectId: project.projectId, missionId: direction.value.missionId, directionId: direction.entityId, autoresearchId: null }, producerAgentIds: producers, reviewerAgentId, independenceCheck: "pass", contractRefs: [{ kind: "contract_evaluation", id: `contract_${direction.entityId.slice(4)}`, hash: direction.value.evaluationContractHash }], requiredArtifactIds: [...new Set(artifacts)], requiredEvidenceIds: [...new Set(evidence)], deterministicPostflight: { status: "pass", validatorRunIds: [reviewType === "direction_closure" ? "validator_direction.closure" : "validator_direction.postflight"] }, criteria: [{ criterionId, statement, required: true, severityIfFailed: "blocking" }], allowedVerdicts: ["PASS", "REVISE", "REDESIGN", "BLOCKED"], issuedAt: new Date().toISOString() }; this.research.submitDaemonRecord(project.projectId, { projectId: project.projectId, missionId: direction.value.missionId, directionId: direction.entityId, autoresearchId: null, experimentId: null, runId: null, jobId: null, agentId: reviewerAgentId }, `task:${taskId}`, request as unknown as JsonValue, `direction-review-request:${taskId}`); return request; }
  private fail(projectId: string, directionId: string, nodeId: string, taskId: string): void { let direction = this.research.direction(projectId, directionId); let node = direction.value.nodes.find((item) => item.id === nodeId)!; if (["working", "reviewing"].includes(node.state)) direction = this.research.transitionDirectionNode(projectId, directionId, direction.version, nodeId, "failed", `direction-failed-${taskId}`); node = direction.value.nodes.find((item) => item.id === nodeId)!; if (node.attempt < node.maximumAttempts) this.research.transitionDirectionNode(projectId, directionId, direction.version, nodeId, "ready", `direction-retry-${taskId}`); else this.research.transitionDirection(projectId, directionId, direction.version, "blocked", `direction-attempts-exhausted-${taskId}`); }
  private async close(project: RegisteredProject, direction: Stored<DirectionProjection>): Promise<void> { direction = this.research.transitionDirection(project.projectId, direction.entityId, direction.version, "reviewing", `direction-final-${createId("cmd")}`); const reviewerId = createId("agt"); const taskId = createId("tsk"); const packets = this.research.records(project.projectId, "task-packet") as unknown as DirectionTaskPacket[]; let producers = packets.filter((packet) => packet.scope.directionId === direction.entityId && packet.assignedRole !== "reviewer").map((packet) => packet.assignedAgentId); if (!producers.length) producers = (this.research.records(project.projectId, "research-director-cycle") as Array<{ directionId?: string; directorAgentId?: string }>).filter((cycle) => cycle.directionId === direction.entityId && cycle.directorAgentId).map((cycle) => cycle.directorAgentId!); const scoped = this.research.submitted(project.projectId).filter((entry) => entry.event.scope.directionId === direction.entityId); const evidence = scoped.filter((entry) => (entry.record as { $schema?: string }).$schema === schemaUri("evidence")).map((entry) => (entry.record as { evidenceId?: string }).evidenceId).filter((id): id is string => Boolean(id)); const results = scoped.filter((entry) => (entry.record as { $schema?: string }).$schema === schemaUri("experiment-result")).map((entry) => entry.record as unknown as { experimentId: string; promotionDecision?: string; deterministicValidation?: string }); const accepted = [...new Set(results.filter((result) => result.promotionDecision === "promoted").map((result) => result.experimentId))]; const rejected = [...new Set(results.filter((result) => result.promotionDecision === "rejected").map((result) => result.experimentId))]; // "held" = met the keep rule and passed experiment Review but no round Review promoted it: neither accepted nor refuted.
    const held = [...new Set(results.filter((result) => result.promotionDecision === "held" && !accepted.includes(result.experimentId)).map((result) => result.experimentId))]; const inconclusive = [...new Set(results.filter((result) => (result.deterministicValidation !== "pass" && !rejected.includes(result.experimentId)) || held.includes(result.experimentId)).map((result) => result.experimentId))]; const autoresearchCompletionPacketIds = scoped.filter((entry) => (entry.record as { $schema?: string }).$schema === schemaUri("autoresearch-completion-packet")).map((entry) => (entry.record as { completionPacketId?: string }).completionPacketId).filter((id): id is string => Boolean(id)); const synthesisArtifactId = this.closureArtifact(project, direction, "synthesis", { question: direction.value.question, decisionUse: direction.value.decisionUse, accepted, rejected, inconclusive, evidence }); const reproducibilityManifestArtifactId = this.closureArtifact(project, direction, "reproducibility", { evaluationContractHash: direction.value.evaluationContractHash, baselineCommit: direction.value.acceptedBaseline?.commit ?? null, graphVersion: direction.value.graphVersion, gitHead: directionGit(project.repositoryRoot, ["rev-parse", "HEAD"]) }); const closureAttempt = scoped.filter((entry) => (entry.record as { $schema?: string }).$schema === schemaUri("direction-closure-packet")).length + 1; const closure: JsonValue = { $schema: schemaUri("direction-closure-packet"), schemaVersion: 1, directionId: direction.entityId, graphVersion: direction.value.graphVersion, closureAttempt, evaluationContractHash: direction.value.evaluationContractHash, questionDisposition: accepted.length ? "supported" : inconclusive.length || !rejected.length ? "inconclusive" : "refuted", answer: accepted.length ? `Reviewed experiments ${accepted.join(", ")} support the bounded Direction decision.` : held.length ? `No experiment was promoted, so adoption is not established. ${held.join(", ")} met the keep rule and passed experiment Review but no round Review promoted ${held.length === 1 ? "it" : "them"}${rejected.length ? `; ${rejected.join(", ")} ${rejected.length === 1 ? "was" : "were"} rejected` : ""}.` : rejected.length && !inconclusive.length ? `Every tested experiment (${rejected.join(", ")}) was rejected under the frozen contract and its guardrails; the bounded change is not supported.` : `No experiment produced an accepted result${inconclusive.length ? `; ${inconclusive.join(", ")} remained inconclusive` : ""}.`, acceptedExperimentIds: accepted, rejectedExperimentIds: rejected, inconclusiveExperimentIds: inconclusive, autoresearchCompletionPacketIds, evidenceIds: evidence, claimEffects: [], failedHypothesisFingerprintIds: rejected.map((id) => `hypothesis_${id.slice(4)}`), limitations: accepted.length ? [] : ["No reviewed promoted Autoresearch experiment was attached"], openDefectIds: [], synthesisArtifactId, reproducibilityManifestArtifactId, deterministicPreReview: { status: "pass", validatorRunIds: ["validator_direction.closure"] }, builtAt: new Date().toISOString() }; this.research.submitDaemonRecord(project.projectId, { projectId: project.projectId, missionId: direction.value.missionId, directionId: direction.entityId, autoresearchId: null, experimentId: null, runId: null, jobId: null, agentId: null }, `direction:${direction.entityId}`, closure, `direction-closure:${direction.entityId}:${closureAttempt}`); const request = this.issueReviewRequest(project, direction, taskId, reviewerId, producers, "direction_closure", "direction_record", direction.entityId, direction.version, direction.entityId, `Closure fidelity for the decision "${direction.value.decisionUse.slice(0, 600)}": the packet's questionDisposition and answer follow from the attached results and Evidence under the frozen contract and its guardrails. An honestly inconclusive or refuted answer passes; an overstated, understated, or unsupported one fails.`, [synthesisArtifactId, reproducibilityManifestArtifactId], evidence); await this.session(project, direction, reviewerId, taskId, "reviewer", `Perform the independent final closure Review for Direction ${direction.entityId}. Audit this canonical closure packet: ${JSON.stringify(closure)}. ${(() => { const outcomes = directionAutoresearchOutcomes(this.research, project.projectId, direction.entityId).digest; return outcomes ? `Resolved Autoresearch outcomes (daemon-authored): ${outcomes}. ` : ""; })()}Review Request: ${JSON.stringify(request)}. ${reviewerInstructions(request)}`); const review = this.research.terminalRecord(project.projectId, taskId, "review-verdict") as DirectionReviewVerdict | undefined; if (!review || !directionReviewPasses(review, request, reviewerId)) throw new Error("Direction final Review did not pass"); this.research.transitionDirection(project.projectId, direction.entityId, direction.version, "closed", `direction-closed-${taskId}`); }
  private closureArtifact(project: RegisteredProject, direction: Stored<DirectionProjection>, name: string, value: JsonValue): string { const root = join(project.repositoryRoot, ".nosh", "direction", direction.entityId); const path = join(root, `${name}.json`); const content = `${canonicalJson(value)}\n`; const digest = sha256(content); const key = digest.slice(7, 23); const write = this.research.beginExternalOperation(project.projectId, "filesystem.write", `direction-file:${direction.entityId}:${name}:${key}`, { path, content, digest }); mkdirSync(root, { recursive: true }); if (!existsSync(path) || sha256(readFileSync(path, "utf8")) !== digest) { const temporary = `${path}.${write.intentId}.tmp`; writeFileSync(temporary, content, "utf8"); renameSync(temporary, path); } if (sha256(readFileSync(path, "utf8")) !== digest) throw new Error("Direction closure file verification failed"); this.research.completeExternalOperation(project.projectId, write.intentId, { path, digest }); const artifactId = `art_${sha256({ directionId: direction.entityId, name, digest }).slice(7, 39)}`; const copy = this.research.beginExternalOperation(project.projectId, "artifact.copy", `direction-artifact:${artifactId}`, { artifactId, path, digest }); const artifact = new ArtifactStore(join(project.repositoryRoot, ".nosh", "artifacts")).add({ artifactId, projectId: project.projectId, kind: `artifact_direction.${name}`, mediaType: "application/json", sourcePath: path, retentionClass: "accepted_evidence" }); this.research.completeExternalOperation(project.projectId, copy.intentId, { artifactId, contentHash: artifact.contentHash, version: artifact.version }); const record: JsonValue = { $schema: schemaUri("artifact"), schemaVersion: 1, artifactId, projectId: project.projectId, kind: `artifact_direction.${name}`, mediaType: "application/json", contentHash: artifact.contentHash, sizeBytes: artifact.sizeBytes, version: artifact.version, producer: { type: "noshd" }, scope: { missionId: direction.value.missionId, directionId: direction.entityId, autoresearchId: null, experimentId: null }, git: null, evaluationContractHash: direction.value.evaluationContractHash, retentionClass: "accepted_evidence", remotePreviewPolicy: "encrypted_allowed", redactionStatus: "checked", createdAt: artifact.createdAt }; this.research.submitDaemonRecord(project.projectId, { projectId: project.projectId, missionId: direction.value.missionId, directionId: direction.entityId, autoresearchId: null, experimentId: null, runId: null, jobId: null, agentId: null }, `artifact:${artifactId}`, record, `direction-artifact-record:${artifactId}`); return artifactId; }
  private async session(project: RegisteredProject, direction: Stored<DirectionProjection>, agentId: string, taskId: string, role: PiSessionOptions["role"], prompt: string, taskPermissions?: PiSessionOptions["taskPermissions"], taskWorkspace?: PiSessionOptions["taskWorkspace"]): Promise<void> {
    if (!this.runtime) {
      await this.agents.start({ projectId: project.projectId, missionId: direction.value.missionId, directionId: direction.entityId, autoresearchId: null, experimentId: null, runId: null, jobId: null, taskId, agentId, role, cwd: taskWorkspace ? taskWorktreePath(project.repositoryRoot, taskWorkspace.worktreeId) : project.repositoryRoot, packagePath: this.packagePath, ...(taskPermissions ? { taskPermissions } : {}), ...(taskWorkspace ? { taskWorkspace } : {}) });
      try { await this.agents.prompt(agentId, prompt); } finally { this.agents.stop(agentId); }
      return;
    }
    const threadId = createId("thr"); const issuedAt = new Date().toISOString(); const key = `runtime:${taskId}`;
    await this.runtime.execute({ $schema: schemaUri("runtime-instruction"), schemaVersion: 1, instructionId: createId("ins"), projectId: project.projectId, idempotencyKey: `${key}:open`, proposedByAgentId: null, issuedAt, operation: "THREAD_OPEN", threadId, taskId, initialAgentId: agentId, ownerScope: { missionId: direction.value.missionId, directionId: direction.entityId, autoresearchId: null, experimentId: null, graphNodeId: null }, role, purpose: `Execute Direction task ${taskId}`, executionMode: "background", parentThreadId: null, inputRefs: [], skillIds: [], capabilities: [], taskPermissions: taskPermissions ?? null, taskWorkspace: taskWorkspace ?? null, budget: { maximumToolCalls: 200, maximumModelTokens: 100_000, maximumWallClockSeconds: 7_200 } });
    try {
      await this.runtime.execute({ $schema: schemaUri("runtime-instruction"), schemaVersion: 1, instructionId: createId("ins"), projectId: project.projectId, idempotencyKey: `${key}:step`, proposedByAgentId: null, issuedAt, operation: "THREAD_STEP", threadId, objective: prompt, expectedEpisodeType: episodeTypeForRole(role), inputRefs: [], skillIds: [] });
    } finally {
      await this.runtime.execute({ $schema: schemaUri("runtime-instruction"), schemaVersion: 1, instructionId: createId("ins"), projectId: project.projectId, idempotencyKey: `${key}:stop`, proposedByAgentId: null, issuedAt: new Date().toISOString(), operation: "STOP", threadId, programId: null, reason: "Task session reached its boundary" });
    }
  }
}

function roleFor(node: GraphNode): "librarian_researcher" | "general_worker" | "reviewer" { if (["literature_review", "librarian_researcher"].includes(node.type)) return "librarian_researcher"; if (["reviewer", "claim_review", "final_review"].includes(node.type)) return "reviewer"; return "general_worker"; }
function event(projectId: string, directionId: string, missionId: string | null, type: string, payload: JsonValue): EventDraft { return { $schema: schemaUri("event"), schemaVersion: 1, retention: "persistent", type, source: "direction_supervisor", scope: { projectId, missionId, directionId, autoresearchId: null, experimentId: null, runId: null, jobId: null, agentId: null }, correlationId: directionId, causationId: null, payload }; }

type DirectionTaskPacket = { $schema: string; schemaVersion: number; templateVersion: string; taskId: string; attempt: number; taskType: string; assignedRole: "librarian_researcher" | "general_worker" | "reviewer"; assignedAgentId: string; scope: { projectId: string; missionId: string | null; directionId: string; autoresearchId: null; experimentId: null; graphNodeId: string }; goalStack: { projectGoalId: string; projectGoalSummary: string; missionCriterionIds: string[]; missionCriterionSummary: string; directionQuestionId: string; directionQuestionSummary: string; nodeObjective: string }; whyNow: string; instructions: string[]; inScope: string[]; outOfScope: string[]; inputArtifactIds: string[]; inputEvidenceIds: string[]; requiredOutputs: Array<{ outputId: string; kind: string; required: boolean }>; acceptanceCriteria: Array<{ criterionId: string; statement: string; validatorIds: string[]; reviewRubricIds: string[]; required: boolean }>; workspace: { worktreeId: string; branch: string; startingCommit: string; writeScopes: string[]; protectedScopes: string[] }; permissions: TaskPermissions; budget: { deadline: string; maximumWallClockSeconds: number; maximumModelTokens: number; maximumToolCalls: number; maximumRepairAttempts: number }; progressPolicy: { milestoneIntervalSeconds: number; emitOnFirstDurableDelta: boolean; emitOnBlocker: boolean; emitOnAnomaly: boolean; maximumSilentSeconds: number }; responseSchema: string; observedVersions: Record<string, number>; lease: { leaseId: string; expiresAt: string; heartbeatSeconds: number }; issuedBy: "research_director"; issuedAt: string };
type DirectionReviewRequest = { $schema: string; schemaVersion: number; reviewRequestId: string; reviewId: string; reviewType: "task" | "direction_closure"; target: { targetType: string; targetId: string; targetVersion: number }; scope: { projectId: string; missionId: string | null; directionId: string; autoresearchId: null }; producerAgentIds: string[]; reviewerAgentId: string; independenceCheck: "pass"; contractRefs: Array<{ kind: string; id: string; hash: string }>; requiredArtifactIds: string[]; requiredEvidenceIds: string[]; deterministicPostflight: { status: "pass"; validatorRunIds: string[] }; criteria: Array<{ criterionId: string; statement: string; required: true; severityIfFailed: "blocking" }>; allowedVerdicts: Array<"PASS" | "REVISE" | "REDESIGN" | "BLOCKED">; issuedAt: string };
type DirectionReviewVerdict = { $schema?: string; reviewId?: string; reviewRequestId?: string; reviewType?: string; target?: { targetType?: string; targetId?: string; targetVersion?: number }; reviewerAgentId?: string; independenceCheck?: string; verdict?: string; criteria?: Array<{ criterionId?: string; status?: string }>; reviewedArtifactIds?: string[]; reviewedEvidenceIds?: string[] };
function directionGit(cwd: string, args: string[]): string { const result = spawnSync("git", ["-C", cwd, ...args], { encoding: "utf8", windowsHide: true, env: worktreeGitEnvironment(cwd) }); if (result.status !== 0) throw new Error(result.stderr.trim() || `git ${args[0]} failed`); return result.stdout.trim(); }
/** The canonical hypothesis node created with every Direction; it depends on the baseline. */
function isHypothesisNode(node: GraphNode): boolean { return node.type === "general_worker" && node.title === "Evaluate bounded hypothesis families"; }
/** The canonical baseline node created with every Direction (see research-control defaultDirectionNodes). */
function isBaselineNode(node: GraphNode): boolean { return node.type === "general_worker" && node.title === "Reproduce accepted baseline" && !node.hardDependencies.length && !node.softDependencies.length; }
function directionPostflight(project: RegisteredProject, packet: DirectionTaskPacket, schema: string, record: JsonValue): string[] { const parsed = validateRecord(schemaUri(schema), record); if (!parsed.ok) return parsed.errors.map((error) => `${error.pointer} ${error.message}`); const value = parsed.value as Record<string, unknown>; const issues: string[] = []; if (value.taskOutcome !== "completed" || value.readyForReview !== true) issues.push("completion is not ready for Review"); const artifacts = new ArtifactStore(join(project.repositoryRoot, ".nosh", "artifacts")); if (schema === "general-worker-completion") { if (value.readyForDeterministicPostflight !== true) issues.push("worker did not request deterministic postflight"); const code = value.codeChanges as { startingCommit: string; endingCommit: string; branch: string; changedPaths: string[]; diffArtifactId: string | null }; issues.push(...validateGitCompletion(taskWorktreePath(project.repositoryRoot, packet.workspace.worktreeId), packet.workspace, code)); const commands = value.commands as Array<{ exitCode: number | null }>; if (commands.some((command) => command.exitCode !== 0)) issues.push("a declared command did not pass"); const criteria = value.criteria as Array<{ criterionId: string; workerClaim: string; validatorRunIds: string[]; artifactIds: string[] }>; for (const criterion of packet.acceptanceCriteria.filter((entry) => entry.required)) { const result = criteria.find((entry) => entry.criterionId === criterion.criterionId); // deferred_to_review: only the independent task Review can establish it, and completion counts it only on that Review's criterion PASS.
      if (!result || !(result.workerClaim === "deferred_to_review" || (result.workerClaim === "satisfied" && result.validatorRunIds.length))) issues.push(`criterion ${criterion.criterionId} lacks a passing validator`); } const ids = [code.diffArtifactId, ...((value.workPerformed as Array<{ artifactIds: string[] }>).flatMap((work) => work.artifactIds)), ...criteria.flatMap((criterion) => criterion.artifactIds)].filter((id): id is string => Boolean(id)); for (const id of ids) try { artifacts.resolve(id); } catch { issues.push(`artifact ${id} does not resolve`); } } else { const librarian = value as unknown as { bibliographyArtifactId: string; reportArtifactId: string; sources: Array<{ artifactId: string }>; findings: Array<{ support: Array<{ artifactId: string }> }> }; for (const id of [librarian.bibliographyArtifactId, librarian.reportArtifactId, ...librarian.sources.map((source) => source.artifactId), ...librarian.findings.flatMap((finding) => finding.support.map((support) => support.artifactId))]) try { artifacts.resolve(id); } catch { issues.push(`artifact ${id} does not resolve`); } } return [...new Set(issues)]; }
function completionRefs(record: JsonValue): { artifactIds: string[]; evidenceIds: string[] } { const value = record as unknown as { workPerformed?: Array<{ artifactIds?: string[] }>; codeChanges?: { diffArtifactId?: string | null }; criteria?: Array<{ artifactIds?: string[] }>; scientificImpact?: { evidenceIds?: string[] }; bibliographyArtifactId?: string; reportArtifactId?: string; sources?: Array<{ artifactId?: string }>; findings?: Array<{ support?: Array<{ artifactId?: string }> }> }; const artifactIds = [value.codeChanges?.diffArtifactId, value.bibliographyArtifactId, value.reportArtifactId, ...(value.workPerformed ?? []).flatMap((entry) => entry.artifactIds ?? []), ...(value.criteria ?? []).flatMap((entry) => entry.artifactIds ?? []), ...(value.sources ?? []).map((entry) => entry.artifactId), ...(value.findings ?? []).flatMap((entry) => (entry.support ?? []).map((support) => support.artifactId))].filter((id): id is string => Boolean(id)); return { artifactIds: [...new Set(artifactIds)], evidenceIds: [...new Set(value.scientificImpact?.evidenceIds ?? [])] }; }
function directionReviewPasses(review: DirectionReviewVerdict, request: DirectionReviewRequest, reviewerId: string): boolean { if (!validateRecord(schemaUri("review-verdict"), review as unknown as JsonValue).ok || review.reviewId !== request.reviewId || review.reviewRequestId !== request.reviewRequestId || review.reviewType !== request.reviewType || review.reviewerAgentId !== reviewerId || review.independenceCheck !== "pass" || review.verdict !== "PASS" || review.target?.targetType !== request.target.targetType || review.target.targetId !== request.target.targetId || review.target.targetVersion !== request.target.targetVersion) return false; if (!request.criteria.every((criterion) => review.criteria?.some((entry) => entry.criterionId === criterion.criterionId && entry.status === "PASS"))) return false; return request.requiredArtifactIds.every((id) => review.reviewedArtifactIds?.includes(id)) && request.requiredEvidenceIds.every((id) => review.reviewedEvidenceIds?.includes(id)); }
